class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        my_dict={}
        for i in nums:
            if i not in my_dict:
                my_dict[i]=1
            else:
                my_dict[i]+=1
        final=sorted(my_dict.items(),key=lambda x: x[1])
        final1=[]
        for i in range(len(final)-1,-1,-1):
            if k==0:
                break
            final1.append(final[i][0])
            k-=1
        return final1
